// ── Fuzzy name matching ───────────────────────────────────────────────────────
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({length: m+1}, (_, i) =>
    Array.from({length: n+1}, (_, j) => i === 0 ? j : j === 0 ? i : 0));
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1] : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
  return dp[m][n];
}

function nameSimilarity(a, b) {
  if (!a || !b) return 0;
  const na = a.toUpperCase().replace(/[^A-Z\s]/g, '').trim();
  const nb = b.toUpperCase().replace(/[^A-Z\s]/g, '').trim();
  if (na === nb) return 1;
  const dist = levenshtein(na, nb);
  const maxLen = Math.max(na.length, nb.length);
  return maxLen === 0 ? 1 : 1 - dist / maxLen;
}

// Similarity ignoring spaces — catches "POUR SAHHMIRI" vs "POURSHAHMIRI"
function nameSimilarityNoSpace(a, b) {
  if (!a || !b) return 0;
  const na = a.toUpperCase().replace(/[^A-Z]/g, '');
  const nb = b.toUpperCase().replace(/[^A-Z]/g, '');
  if (!na || !nb) return 0;
  if (na === nb) return 1;
  const dist = levenshtein(na, nb);
  return 1 - dist / Math.max(na.length, nb.length);
}

// Best similarity across all tokens in a compound name vs a target
// e.g. "BENITEZ MONTES" tokens vs "BENITEZ" → 1.0
function bestTokenSim(compound, target) {
  if (!compound || !target) return 0;
  const tokens = compound.toUpperCase().replace(/[^A-Z\s]/g,'').trim().split(/\s+/);
  const t = target.toUpperCase().replace(/[^A-Z\s]/g,'').trim();
  return Math.max(...tokens.map(tok => nameSimilarity(tok, t)));
}

function parseName(nameStr) {
  if (!nameStr) return {last:'', first:'', tokens:[]};
  const s = nameStr.trim();
  let last, first, rest;
  if (s.includes(',')) {
    const parts = s.split(',').map(p => p.trim());
    last = parts[0];
    const firstParts = (parts[1]||'').trim().split(/\s+/);
    first = firstParts[0] || '';
    rest  = firstParts.slice(1);
  } else {
    const parts = s.split(/\s+/);
    last  = parts[parts.length-1] || '';
    first = parts[0] || '';
    rest  = parts.slice(1, parts.length-1);
  }
  // all name tokens for broad searching
  const tokens = [last, first, ...rest].map(t=>t.toUpperCase().replace(/[^A-Z]/g,'')).filter(Boolean);
  return {last, first, rest: rest || [], tokens};
}

// Compute a composite name match score between a claim and an entry,
// handling compound last names, reversed order, and partial first names.
function computeNameScore(claim, entry) {
  const ep = parseName(entry.patientName);
  const cl = {last: claim.last||'', first: claim.first||''};

  // ── straight match ──
  const lastStraight  = Math.max(nameSimilarity(cl.last, ep.last), nameSimilarityNoSpace(cl.last, ep.last));
  const firstStraight = nameSimilarity(cl.first, ep.first);

  // ── reversed match (EOB has "DAVID, LIN" but entry is "LIN, DAVID") ──
  const lastReversed  = Math.max(nameSimilarity(cl.last, ep.first), nameSimilarityNoSpace(cl.last, ep.first));
  const firstReversed = Math.max(nameSimilarity(cl.first, ep.last), nameSimilarityNoSpace(cl.first, ep.last));

  // ── compound last name: any token of EOB last matches entry last ──
  // handles "BENITEZ MONTES" → "BENITEZ"
  const lastTokenVsEntryLast  = bestTokenSim(cl.last, ep.last);
  const entryLastVsClaimTokens = bestTokenSim(ep.last, cl.last);

  // ── assemble straight combined ──
  // Note: do NOT use claim tokens vs entry first — short token levenshtein gives false positives
  const straightLast  = Math.max(lastStraight, lastTokenVsEntryLast, entryLastVsClaimTokens);
  const straightFirst = firstStraight;
  const straightCombined = straightLast * 0.55 + straightFirst * 0.45;

  // ── reversed combined ──
  const reversedCombined = lastReversed * 0.55 + firstReversed * 0.45;

  // ── first-name-only match (for maiden/married name cases) ──
  // If first names are an exact or near-exact match, give a partial score
  // so the entry can surface as a suggestion even with totally different last names
  const firstExact = Math.max(firstStraight, firstReversed);

  const nameSim = Math.max(straightCombined, reversedCombined);

  return { nameSim, straightLast, straightFirst, firstExact, reversedCombined };
}

function toDateStr(val) {
  if (!val) return null;
  if (typeof val === 'string') {
    // 4-digit year: M/D/YYYY
    const m4 = val.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (m4) return `${m4[3]}-${m4[1].padStart(2,'0')}-${m4[2].padStart(2,'0')}`;
    // 2-digit year: M/D/YY
    const m2 = val.match(/(\d{1,2})\/(\d{1,2})\/(\d{2})$/);
    if (m2) { const yr = parseInt(m2[3]); return `${yr < 50 ? '20' : '19'}${m2[3]}-${m2[1].padStart(2,'0')}-${m2[2].padStart(2,'0')}`; }
    if (val.match(/^\d{4}-\d{2}-\d{2}/)) return val.slice(0,10);
  }
  if (val instanceof Date) return val.toISOString().slice(0,10);
  return null;
}

function normalizeDate(val) {
  if (!val) return null;
  const s = String(val).trim();
  // M/D/YYYY or MM/DD/YYYY
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}`;
  // Already YYYY-MM-DD
  if (s.match(/^\d{4}-\d{2}-\d{2}/)) return s.slice(0,10);
  return s;
}

function daysDiff(a, b) {
  if (!a || !b) return 999;
  const na = normalizeDate(a);
  const nb = normalizeDate(b);
  if (!na || !nb) return 999;
  return Math.abs((new Date(na+'T12:00:00') - new Date(nb+'T12:00:00')) / 86400000);
}

// ── Parse EyeMed Excel ────────────────────────────────────────────────────────
function parseEyeMedExcel(buf) {
  const wb = XLSX.read(buf, {type:'array', cellDates:true});
  const ws = wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(ws, {header:1, defval:null});
  const headers = (rows[0]||[]).map(h => h ? String(h).trim() : '');

  // Fuzzy column finder — exact match first, then case-insensitive substring
  const findCol = (...names) => {
    for (const name of names) {
      const exact = headers.indexOf(name);
      if (exact >= 0) return exact;
    }
    for (const name of names) {
      const idx = headers.findIndex(h => h.toLowerCase().includes(name.toLowerCase()));
      if (idx >= 0) return idx;
    }
    return -1;
  };

  const iMember   = findCol('Member Name', 'Member', 'Patient Name', 'Patient');
  const iProvider = findCol('Provider Name', 'Provider', 'Doctor');
  const iDOS      = findCol('Date of Service', 'Service Date', 'DOS');
  const iClaimNet = findCol('Claim Net Payment', 'Net Payment', 'Amount Paid', 'Payment Amount', 'Amount');
  const iClaimNum = findCol('Claim Number', 'Claim #', 'Claim No', 'ClaimNumber');

  console.log('[EOB Excel] headers:', headers);
  console.log('[EOB Excel] col indices — member:', iMember, 'provider:', iProvider, 'dos:', iDOS, 'claimNet:', iClaimNet, 'claimNum:', iClaimNum);

  // Extract disbursement metadata
  const iDisbDate = findCol('Payment Date','Disbursement Date','Check Date','EFT Date','Paid Date');
  const iDisbId   = findCol('Check Number','EFT Number','Payment Reference','Check #','EFT #','Remittance ID','Payment ID');

  // Grab from first data row that has values
  let metaDate = null, metaId = null;
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    if (!r) continue;
    if (!metaDate && iDisbDate >= 0 && r[iDisbDate]) metaDate = toDateStr(r[iDisbDate]) || String(r[iDisbDate]);
    if (!metaId   && iDisbId   >= 0 && r[iDisbId])   metaId   = String(r[iDisbId]).trim();
    if (metaDate && metaId) break;
  }
  // Fallback: use the most recent DOS as the disbursement date proxy
  if (!metaDate) {
    const allDates = [];
    for (let i = 1; i < rows.length; i++) {
      const r = rows[i];
      if (r && iDOS >= 0 && r[iDOS]) { const d = toDateStr(r[iDOS]); if (d) allDates.push(d); }
    }
    if (allDates.length) metaDate = allDates.sort().pop(); // most recent DOS
  }

  const claimsSeen = new Set();
  const claims = [];

  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    if (!r) continue;
    const claimNum   = iClaimNum >= 0 ? String(r[iClaimNum]||'').trim() : '';
    const memberName = r[iMember] ? String(r[iMember]).trim() : null;
    const provName   = r[iProvider] ? String(r[iProvider]).trim() : null;
    const dos        = toDateStr(r[iDOS]);
    const netPay     = parseFloat(r[iClaimNet]) || 0;

    if (!memberName || !dos) continue;
    // Use claimNum as dedup key when available; fall back to memberName+dos
    const dedupKey = claimNum || (memberName + '|' + dos);
    if (claimsSeen.has(dedupKey)) continue;
    claimsSeen.add(dedupKey);

    const {last, first} = parseName(memberName);
    const {last: drLast} = parseName(provName);

    claims.push({claimNum, memberName, last, first, doctor: drLast, dos, amount: netPay, negative: netPay < 0, source: 'eyemed'});
  }
  return { claims, meta: { date: metaDate, refId: metaId } };
}

// ── Parse EyeMed/VSP remittance text (paste from PDF) — no API needed ─────────
function parseRemittanceText(rawText) {
  const claims = [];
  const lines = rawText.split(/\n/);

  // Pattern: claim block starts with a line like:
  // "99825876439 NIMAIYAR, RAHUL"  (claim# then patient name in ALL CAPS)
  // Then a few lines of detail ending with "Total Auth: XXXXXXX ... amount"
  const claimHeaderRe = /^\s*(\d{8,12})\s+([A-Z][A-Z ,.'\-]+[A-Z])\s*$/;
  const totalAuthRe = /Total Auth:.*?([\d.]+)\s*$/;
  const dosRe = /^\s*(\d{1,2}\/\d{1,2}\/\d{4})\s+\d/;
  const providerRe = /([A-Z][A-Z]+)\s*$/; // last word of provider line (e.g. "CHRISTINE YANG" → "YANG")

  let i = 0;
  while (i < lines.length) {
    const headerMatch = lines[i].match(claimHeaderRe);
    if (headerMatch) {
      const claimNum = headerMatch[1];
      const patientName = headerMatch[2].trim();

      // Look ahead for provider line (next line after claim#) and DOS + Total Auth
      let doctor = '';
      let dos = '';
      let amount = 0;

      // Provider is on the line after patient name (contains provider last name)
      if (i + 1 < lines.length) {
        const provLine = lines[i + 1];
        // Provider line format: "policyNum SUBSCRIBER_NAME PROVIDER_ID PROVIDER_NAME"
        // Extract last word before end of line as doctor last name
        const provWords = provLine.trim().split(/\s+/);
        if (provWords.length >= 2) {
          doctor = provWords[provWords.length - 1]; // last word = last name
        }
      }

      // Scan ahead for DOS and Total Auth
      for (let j = i + 1; j < Math.min(i + 20, lines.length); j++) {
        // Get first DOS if not found yet
        if (!dos) {
          const dosMatch = lines[j].match(dosRe);
          if (dosMatch) dos = dosMatch[1];
        }
        // Total Auth line has the payment amount (last number)
        const totalMatch = lines[j].match(totalAuthRe);
        if (totalMatch) {
          amount = parseFloat(totalMatch[1]) || 0;
          i = j; // advance past this claim block
          break;
        }
      }

      if (patientName && amount !== undefined && dos) {
        const {last, first} = parseName(patientName);
        const dosFormatted = toDateStr(dos) || dos;
        claims.push({
          claimNum,
          memberName: patientName,
          last, first,
          doctor,
          dos: dosFormatted,
          amount,
          negative: amount < 0,
          source: 'vsp'
        });
      }
    }
    i++;
  }

  // Extract disbursement date and check/EFT number from header lines (before first claim)
  let metaDate = null, metaId = null;
  const header = lines.slice(0, 40).join('\n');
  const dateM  = header.match(/(?:Check Date|Payment Date|Paid Date|EFT Date|Disbursement Date)[:\s]+(\d{1,2}\/\d{1,2}\/\d{2,4})/i)
               || header.match(/(\d{1,2}\/\d{1,2}\/\d{4})/); // fallback: first date found
  if (dateM) metaDate = toDateStr(dateM[1]) || dateM[1];
  const idM = header.match(/(?:Check (?:Number|#|No\.?)|EFT (?:Number|#)|Payment (?:Reference|ID)|Remittance (?:ID|#))[:\s#]+([A-Z0-9\-]+)/i);
  if (idM) metaId = idM[1].trim();
  // Fallback: use latest DOS
  if (!metaDate && claims.length) metaDate = [...claims].sort((a,b)=>a.dos>b.dos?-1:1)[0].dos;

  return { claims, meta: { date: metaDate, refId: metaId } };
}


// ── Parse EyeMed Text (pasted from PDF) ──────────────────────────────────────
function parseEyeMedText(rawText) {
  const claims = [];
  const lines = rawText.split(/\n/);

  // Split into claim blocks by "Member Name:" lines.
  // Member Name appears BEFORE Claim # in the PDF, so splitting on Claim # caused
  // each block to capture the next patient's name — a consistent off-by-one.
  const blockStarts = [];
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].match(/^\s*Member Name:\s*[A-Z]/i)) blockStarts.push(i);
  }

  for (let bi = 0; bi < blockStarts.length; bi++) {
    const start = blockStarts[bi];
    const end = bi + 1 < blockStarts.length ? blockStarts[bi+1] : lines.length;
    const block = lines.slice(start, end);

    let claimNum = '', patientName = '', doctor = '', dos = '', amount = 0;

    for (let j = 0; j < block.length; j++) {
      const line = block[j].trim();

      // Claim number
      const claimM = line.match(/^Claim #:\s*(\d+)/i);
      if (claimM) claimNum = claimM[1];

      // Member Name (patient) — can appear anywhere in block
      const memberM = line.match(/^Member Name:\s*([A-Z][A-Z ,.'\-]+)/i);
      if (memberM) patientName = memberM[1].trim();

      // Provider last name
      const provM = line.match(/^Provider Name:\s*([A-Z][A-Z]+),/i);
      if (provM) doctor = provM[1];

      // DOS: line starting with date (MM/DD/YY or MM/DD/YYYY) followed by service code
      if (!dos) {
        const dosM = line.match(/^(\d{1,2}\/\d{1,2}\/\d{2,4})\s+\d{5}/);
        if (dosM) dos = dosM[1];
      }

      // Claim Net Payment: amount is 3 lines after the "Claim Net Payment:" line
      if (line.match(/^Claim Net Payment:/i)) {
        // Skip blank/zero lines to find the actual payment
        // Format: line+1=$0.00 (chargebacks), line+2=$0.00, line+3=$XX.XX (payment)
        for (let k = j+1; k < Math.min(j+5, block.length); k++) {
          const amtM = block[k].trim().match(/^\$([\d,]+\.\d{2})$/);
          if (amtM) {
            const val = parseFloat(amtM[1].replace(',',''));
            if (val > 0) { amount = val; break; }
          }
        }
      }
    }

    // Member name may appear at end of PREVIOUS block — check lines before this block
    if (!patientName && start > 0) {
      for (let k = start - 1; k >= Math.max(0, start - 5); k--) {
        const memberM = lines[k].trim().match(/^Member Name:\s*([A-Z][A-Z ,.'\-]+)/i);
        if (memberM) { patientName = memberM[1].trim(); break; }
      }
    }

    // Claim Net Payment may appear at the START of this block if the claim spanned a page
    // break ("Continued from previous page"). Scan first ~10 lines after the label.
    if (amount === 0) {
      let foundLabel = false;
      for (let k = 0; k < Math.min(10, block.length); k++) {
        const ln = block[k].trim();
        if (ln.match(/^Claim Net Payment:/i)) { foundLabel = true; continue; }
        if (foundLabel) {
          const amtM = ln.match(/^\$([\d,]+\.\d{2})$/);
          if (amtM) {
            const val = parseFloat(amtM[1].replace(',', ''));
            if (val > 0) { amount = val; break; }
          }
        }
      }
    }

    // If still no amount, the Claim Net Payment was in the PREVIOUS block's tail
    // (page break split the totals section). Scan backwards from end of previous block.
    if (amount === 0 && bi > 0) {
      const prevLines = lines.slice(blockStarts[bi - 1], start);
      let foundLabel = false;
      for (let k = 0; k < prevLines.length; k++) {
        if (prevLines[k].trim().match(/^Claim Net Payment:/i)) { foundLabel = true; break; }
      }
      if (foundLabel) {
        for (let k = prevLines.length - 1; k >= 0; k--) {
          const amtM = prevLines[k].trim().match(/^\$([\d,]+\.\d{2})$/);
          if (amtM) {
            const val = parseFloat(amtM[1].replace(',', ''));
            if (val > 0) { amount = val; break; }
          }
        }
      }
    }

    if (claimNum && patientName && amount > 0) {
      const {last, first} = parseName(patientName);
      // Convert 2-digit year: 04/14/26 → 04/14/2026
      const dosNorm = dos.replace(/(\d{1,2}\/\d{1,2}\/)(\/d{2})$/, (_, prefix, yr) =>
        prefix + (parseInt(yr) < 50 ? '20' : '19') + yr);
      claims.push({
        claimNum,
        memberName: patientName,
        last, first,
        doctor,
        dos: toDateStr(dos) || '',
        amount,
        negative: false,
        source: 'eyemed_text'
      });
    }
  }

  // Extract disbursement metadata from header lines (before first claim block)
  let metaDate = null, metaId = null;
  const firstBlockStart = blockStarts[0] ?? lines.length;
  const header = lines.slice(0, Math.min(firstBlockStart, 40)).join('\n');
  const dateM = header.match(/(?:Payment Date|Check Date|Paid Date|Disbursement Date)[:\s]+(\d{1,2}\/\d{1,2}\/\d{2,4})/i)
              || header.match(/(\d{1,2}\/\d{1,2}\/\d{4})/);
  if (dateM) metaDate = toDateStr(dateM[1]) || dateM[1];
  const idM = header.match(/(?:Check (?:Number|#|No\.?)|EFT (?:Number|#)|Payment (?:Reference|ID)|Remittance (?:ID|#))[:\s#]+([A-Z0-9\-]+)/i);
  if (idM) metaId = idM[1].trim();
  if (!metaDate && claims.length) metaDate = [...claims].sort((a,b)=>a.dos>b.dos?-1:1)[0].dos;

  return { claims, meta: { date: metaDate, refId: metaId } };
}

// ── Match EOB claims to billing entries ───────────────────────────────────────

// Map EOB source to expected payor codes in billing entries
const EYEMED_PAYORS = ['EM','Aetna','Cigna','Humana','BCBS'];
const VSP_PAYORS = ['VSP','Davis','DV','Spectera','UHC','Superior','SUP','Colonial','COL','Guardian','MetLife','FEP','NVA','VBA','Avesis'];

function payorMatchesSource(entry, source) {
  if (!source) return true; // no filter
  const p = (entry.payor1||'').toUpperCase();
  if (source === 'eyemed') {
    return EYEMED_PAYORS.some(em => p.includes(em.toUpperCase()));
  } else {
    // VSP/other — not eyemed
    return !EYEMED_PAYORS.some(em => p.includes(em.toUpperCase()));
  }
}

function matchClaims(claims, entries) {
  return claims.map(claim => {
    let bestEntry = null, bestScore = 0, bestNameSim = 0;

    for (const entry of entries) {
      if (!entry.payor1 || entry.payor1 === 'Self') continue;
      const dd = daysDiff(claim.dos, entry.date);
      if (dd > 7) continue;

      const { nameSim, straightLast, straightFirst, firstExact } = computeNameScore(claim, entry);

      // Nickname fallback
      let finalNameSim = nameSim;
      if (entry.nickname) {
        const { nameSim: nickSim } = computeNameScore(
          claim,
          { patientName: entry.nickname }
        );
        finalNameSim = Math.max(finalNameSim, nickSim);
      }

      // Hard reject: same last name, completely different first names
      // (e.g. WANG,RACHEL vs WANG,YUFEI on different DOS shouldn't merge)
      // Only apply when DOS also doesn't match perfectly
      if (straightLast > 0.85 && straightFirst < 0.35 && firstExact < 0.35 && dd > 0) continue;

      // Suggestion floor: need either a solid last name match OR a strong first name match
      // Pure nameSim floor alone lets short-string levenshtein noise through
      const clearsSuggestionBar = (nameSim >= 0.50 && (straightLast >= 0.50 || firstExact >= 0.85))
                                || (firstExact >= 0.90 && dd <= 1); // maiden/married name
      if (!clearsSuggestionBar) continue;

      const dateScore = dd === 0 ? 1 : dd <= 1 ? 0.9 : dd <= 2 ? 0.8 : dd <= 3 ? 0.7 : 0.5;
      const docScore  = claim.doctor && entry.doctorId
        ? nameSimilarity(claim.doctor.toLowerCase(), entry.doctorId.toLowerCase()) > 0.7 ? 0.1 : 0
        : 0;

      const score = finalNameSim * 0.55 + dateScore * 0.35 + docScore + 0.1;

      if (score > bestScore) { bestScore = score; bestEntry = entry; bestNameSim = finalNameSim; }
    }

    const dd = bestEntry ? daysDiff(claim.dos, bestEntry.date) : null;

    // Amount check
    let amtOk = false, whichPayor = null;
    if (bestEntry) {
      const ins1 = parseFloat(bestEntry.ins1Amt) || parseFloat(bestEntry.ins) || 0;
      const ins2 = parseFloat(bestEntry.ins2Amt) || 0;
      const ins3 = parseFloat(bestEntry.ins3Amt) || 0;
      const tol  = 1.0;
      if (ins1 > 0 && Math.abs(claim.amount - ins1) <= tol) { amtOk = true; whichPayor = 1; }
      else if (ins2 > 0 && Math.abs(claim.amount - ins2) <= tol) { amtOk = true; whichPayor = 2; }
      else if (ins3 > 0 && Math.abs(claim.amount - ins3) <= tol) { amtOk = true; whichPayor = 3; }
    }

    const hasMultipleIns = bestEntry && (bestEntry.payor2 || bestEntry.payor3);

    // Confidence thresholds:
    //   ≥ 0.75 nameSim + amtOk + dd≤3 → confirmed/partial (auto-applied)
    //   ≥ 0.65 nameSim or special cases → suggested (human review, INS EXP shown)
    //   < 0.65 but firstExact match → suggested (maiden/married name etc.)
    //   no bestEntry → unmatched
    const isHighConfidence = bestNameSim >= 0.75 && amtOk && dd <= 3;
    const isSuggestion     = bestEntry && !isHighConfidence;

    let status, insPaidState;
    if (!bestEntry)          { status = 'unmatched';       insPaidState = null; }
    else if (claim.negative) { status = 'chargeback';      insPaidState = 'bad'; }
    else if (isHighConfidence && hasMultipleIns) { status = 'matched'; insPaidState = 'partial'; }
    else if (isHighConfidence)                   { status = 'matched'; insPaidState = 'confirmed'; }
    else if (dd > 3)         { status = 'date_mismatch';   insPaidState = 'suggested'; }
    else if (!amtOk)         { status = 'amount_mismatch'; insPaidState = 'suggested'; }
    else                     { status = 'low_confidence';  insPaidState = 'suggested'; }

    return {claim, entry: bestEntry, score: bestScore, status, insPaidState, amtOk, dd, whichPayor};
  });
}

// ── Modal ─────────────────────────────────────────────────────────────────────
export default function EOBImportModal({entries, onClose, onApplied}) {
  const [step, setStep]           = useState('choose');
  const [eobType, setEobType]     = useState('eyemed');
  const [processing, setProcessing] = useState(false);
  const [progress, setProgress]   = useState('');
  const [results, setResults]     = useState(null);
  const [error, setError]         = useState('');
  const fileRef = useRef();

  const handleFile = async (file) => {
    if (!file) return;
    setProcessing(true); setError('');
    try {
      let claims = [], importMeta = { date: null, refId: null, source: eobType };

      if (eobType === 'eyemed') {
        setProgress('Parsing EyeMed Excel...');
        const buf = await file.arrayBuffer();
        const parsed = parseEyeMedExcel(buf);
        console.log('[EOB] EyeMed Excel parsed:', parsed.claims.length, 'claims', 'meta:', parsed.meta);
        if (parsed.claims.length === 0) console.warn('[EOB] EyeMed Excel: 0 claims — check column names in file');
        claims = parsed.claims; importMeta = { ...parsed.meta, source: 'eyemed' };
      } else if (eobType === 'eyemed_text') {
        setProgress('Parsing EyeMed text...');
        const text = typeof file === 'string' ? file : await file.text();
        const parsed = parseEyeMedText(text);
        console.log('[EOB] EyeMed text parsed:', parsed.claims.length, 'claims');
        claims = parsed.claims; importMeta = { ...parsed.meta, source: 'eyemed_text' };
      } else {
        setProgress('Parsing remittance text...');
        const text = typeof file === 'string' ? file : await file.text();
        const parsed = parseRemittanceText(text);
        console.log('[EOB] VSP text parsed:', parsed.claims.length, 'claims');
        claims = parsed.claims; importMeta = { ...parsed.meta, source: 'vsp' };
      }

      console.log('[EOB] entries available for matching:', entries.length);
      setProgress(`Matching ${claims.length} claims to billing records...`);
      const matchResults = matchClaims(claims, entries);
      console.log('[EOB] matchResults:', matchResults.length, 'results');
      const statusBreakdown = matchResults.reduce((acc, r) => { acc[r.status] = (acc[r.status]||0)+1; return acc; }, {});
      console.log('[EOB] status breakdown:', statusBreakdown);

      setProgress('Writing to billing records...');
      const toApply = matchResults.filter(r => r.status !== 'unmatched');
      const updated = [];

      for (const r of toApply) {
        // Only auto-apply confirmed and partial matches — not suggested
        if (r.insPaidState === 'suggested') continue;
        // Skip if already fully paid (duplicate upload protection)
        const alreadyPaid = r.entry.insurancePaid1 && (!r.entry.payor2 || r.entry.insurancePaid2) && (!r.entry.payor3 || r.entry.insurancePaid3);
        if (alreadyPaid) { r.status = 'duplicate'; continue; }
        const paidUpdates = {};
        if (r.whichPayor === 2) { paidUpdates.insurancePaid2 = String(Math.abs(r.claim.amount)); if (r.claim.claimNum) paidUpdates.claimNumber2 = r.claim.claimNum; }
        else if (r.whichPayor === 3) { paidUpdates.insurancePaid3 = String(Math.abs(r.claim.amount)); if (r.claim.claimNum) paidUpdates.claimNumber3 = r.claim.claimNum; }
        else { paidUpdates.insurancePaid1 = String(Math.abs(r.claim.amount)); if (r.claim.claimNum) paidUpdates.claimNumber = r.claim.claimNum; }
        const mergedEntry = {...r.entry, ...paidUpdates};
        const totalPaid = (parseFloat(mergedEntry.insurancePaid1)||0)+(parseFloat(mergedEntry.insurancePaid2)||0)+(parseFloat(mergedEntry.insurancePaid3)||0);
        const allPaid = (!mergedEntry.payor1||mergedEntry.payor1==='Self'||(parseFloat(mergedEntry.insurancePaid1)||0)>0) &&
                     (!mergedEntry.payor2||(parseFloat(mergedEntry.insurancePaid2)||0)>0) &&
                     (!mergedEntry.payor3||(parseFloat(mergedEntry.insurancePaid3)||0)>0);
        const upd = {
          ...mergedEntry,
          insPaidState: r.insPaidState,
          updatedAt: new Date().toISOString(),
          ins: allPaid ? String(totalPaid) : (r.entry.ins || ''),
        };
        if (r.status === 'chargeback') {
          upd.attn = `Chargeback: ${r.claim.source.toUpperCase()} subtracted $${Math.abs(r.claim.amount)} (DOS ${r.claim.dos})`;
          upd.attnResolved = false;
        }
        if (r.status === 'date_mismatch') {
          upd.attn = `EOB date mismatch: EOB shows ${r.claim.dos}, billing shows ${r.entry.date}`;
          upd.attnResolved = false;
        }
        await setDoc(doc(db, 'billingEntries', r.entry.id), upd);
        updated.push(upd);
      }

      setResults({matchResults, applied: updated.length});
      // Save unmatched and suggested to pending EOB queue,
      // deduplicating against claimNums already in any existing pending batch.
      const pendingCandidates = matchResults.filter(r =>
        r.status === 'unmatched' || r.insPaidState === 'suggested'
      );
      console.log('[EOB] pendingCandidates:', pendingCandidates.length);
      if (pendingCandidates.length > 0) {
        // Load existing pending claimNums to avoid duplicate entries
        const { getDocs, collection: col } = await import('firebase/firestore');
        const existingSnap = await getDocs(col(db, 'pendingEOB'));
        const existingClaimNums = new Set();
        existingSnap.forEach(d => {
          (d.data().claims || []).forEach(c => {
            if (c.claimNum) existingClaimNums.add(String(c.claimNum));
          });
        });

        // Count duplicates for reporting but don't block — always save new batch
        const duplicateCount = pendingCandidates.filter(r =>
          r.claim.claimNum && existingClaimNums.has(String(r.claim.claimNum))
        ).length;

        if (duplicateCount > 0) {
          matchResults._duplicateSkipped = duplicateCount;
          matchResults._totalPending = pendingCandidates.length;
        }

        const newClaims = pendingCandidates;

        console.log('[EOB] existingClaimNums in pending:', existingClaimNums.size);
        console.log('[EOB] newClaims to save:', newClaims.length, 'duplicates flagged:', matchResults._duplicateSkipped||0);

        if (newClaims.length > 0) {
          const pendingDoc = {
            importedAt: new Date().toISOString(),
            source: eobType,
            claims: newClaims.map(r => ({
              claimNum: r.claim.claimNum,
              memberName: r.claim.memberName,
              dos: r.claim.dos,
              amount: r.claim.amount,
              doctor: r.claim.doctor || '',
              status: r.status,
              reason: r.status === 'amount_mismatch' ? `Amt: EOB $${r.claim.amount} vs Exp $${parseFloat(r.entry?.ins||0).toFixed(2)}` :
                      r.status === 'date_mismatch' ? `Date: EOB ${r.claim.dos} vs Entry ${r.entry?.date||'?'}` :
                      r.status === 'low_confidence' ? `Low confidence (${r.score ? (r.score*100).toFixed(0)+'%' : '?'})` :
                      r.status === 'unmatched' ? 'No matching patient found' : r.status,
              suggestedEntryId: r.entry?.id || null,
              suggestedEntryName: r.entry?.patientName || null,
              suggestedEntryDate: r.entry?.date || null,
              suggestedScore: r.score || 0,
            }))
          };
          await setDoc(doc(db, 'pendingEOB', `eob_${Date.now()}`), pendingDoc);
        }
      }
      onApplied(updated, importMeta);
      setStep('report');
    } catch(e) {
      setError(e.message || String(e));
    } finally {
      setProcessing(false); setProgress('');
    }
  };

  const STATUS = {
    matched:        {bg:'#D1FAE5', color:'#065F46',  label:'✓ Confirmed'},
    amount_mismatch:{bg:'#FCE7F3', color:'#9D174D',  label:'~ Amt differs'},
    chargeback:     {bg:'#FEE2E2', color:'#DC2626',  label:'! Chargeback'},
    date_mismatch:  {bg:'#FEF3C7', color:'#92400E',  label:'⚠ Date off'},
    unmatched:      {bg:'#F1F5F9', color:'#64748B',  label:'? No match'},
    partial:        {bg:'#FEF3C7', color:'#92400E',  label:'◑ Partial (more ins pending)'},
    suggested:      {bg:'#FDF4FF', color:'#7E22CE',  label:'? Suggested (needs review)'},
    low_confidence: {bg:'#FDF4FF', color:'#7E22CE',  label:'? Low confidence (needs review)'},
    duplicate:      {bg:'#F0FDF4', color:'#166534',  label:'↩ Already processed'},
  };

  const counts = results
    ? Object.fromEntries(Object.keys(STATUS).map(k => [k, results.matchResults.filter(r=>r.status===k).length]))
    : {};

  return (
    <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.5)',zIndex:1000,display:'flex',alignItems:'center',justifyContent:'center',padding:16,overflow:'auto'}}>
      <div style={{background:'white',borderRadius:14,maxWidth:740,width:'100%',maxHeight:'90vh',overflow:'auto',padding:24,boxShadow:'0 8px 40px rgba(0,0,0,0.2)'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
          <h3 style={{fontFamily:"'DM Serif Display',serif",fontSize:18,color:'#1B3A5C'}}>Import EOB / Remittance</h3>
          <button onClick={onClose} style={{background:'none',border:'none',fontSize:20,cursor:'pointer',color:'#94A3B8'}}>✕</button>
        </div>

        {error && <div style={{background:'#FEE2E2',borderRadius:8,padding:'10px 14px',color:'#DC2626',fontSize:12,marginBottom:14}}>{error}</div>}

        {step === 'choose' && (
          <div>
            <p style={{fontSize:12,color:'#64748B',marginBottom:14}}>Upload a remittance file. Payments are matched to billing entries automatically and applied in bulk.</p>
            <div style={{display:'flex',gap:8,marginBottom:14,flexWrap:'wrap'}}>
              {[['eyemed','EyeMed Excel (.xlsx)','📊','EyeMed Excel disbursement files'],['eyemed_text','EyeMed (Paste Text)','📋','Paste text from EyeMed PDF remittance'],['vsp','VSP / Other (Paste Text)','📄','VSP, Davis, Spectera — paste text from PDF']].map(([val,label,icon,desc])=>(
                <button key={val} onClick={()=>setEobType(val)}
                  style={{flex:1,padding:'14px',borderRadius:10,border:`2px solid ${eobType===val?'#1B3A5C':'#E2E8F0'}`,background:eobType===val?'#EFF6FF':'white',cursor:'pointer',textAlign:'left'}}>
                  <div style={{fontSize:22,marginBottom:4}}>{icon}</div>
                  <div style={{fontSize:13,fontWeight:700,color:eobType===val?'#1B3A5C':'#475569',marginBottom:2}}>{label}</div>
                  <div style={{fontSize:11,color:'#94A3B8'}}>{desc}</div>
                </button>
              ))}
            </div>

            {processing ? (
              <div style={{background:'#F0F9FF',borderRadius:8,padding:'16px',textAlign:'center'}}>
                <div style={{fontSize:13,color:'#1D4ED8',fontWeight:600,marginBottom:4}}>{progress}</div>
                <div style={{fontSize:11,color:'#94A3B8'}}>Please wait — do not close this window</div>
              </div>
            ) : eobType==='eyemed' ? (
              <>
                <input ref={fileRef} type="file" accept=".xlsx,.xls" style={{display:'none'}} onChange={e=>handleFile(e.target.files[0])}/>
                <button onClick={()=>fileRef.current.click()}
                  style={{background:'#1B3A5C',color:'white',border:'none',borderRadius:8,padding:'11px 24px',cursor:'pointer',fontSize:14,fontWeight:600,width:'100%'}}>
                  Select Excel (.xlsx) File
                </button>
              </>
            ) : (
              <div style={{width:'100%'}}>
                <p style={{fontSize:11,color:'#64748B',marginBottom:6}}>Open PDF → Select All (Ctrl+A) → Copy → Paste below, then click Import</p>
                <textarea
                  id="eob-paste-area"
                  placeholder="Paste remittance text here..."
                  rows={8}
                  style={{width:'100%',fontFamily:'monospace',fontSize:10,border:'1px solid #E2E8F0',borderRadius:6,padding:'8px',resize:'vertical',boxSizing:'border-box',marginBottom:8}}
                />
                <button onClick={()=>{
                  const txt=document.getElementById('eob-paste-area').value.trim();
                  if(txt.length>50)handleFile(txt);
                }} style={{background:'#1B3A5C',color:'white',border:'none',borderRadius:8,padding:'10px 24px',cursor:'pointer',fontSize:13,fontWeight:600,width:'100%'}}>
                  Import Remittance Text
                </button>
              </div>
            )}
          </div>
        )}


        {step === 'report' && results && (
          <div>
            <div style={{display:'grid',gridTemplateColumns:'repeat(5,1fr)',gap:8,marginBottom:14}}>
              {Object.entries(STATUS).map(([key,{bg,color,label}])=>(
                <div key={key} style={{background:bg,borderRadius:8,padding:'10px',textAlign:'center'}}>
                  <div style={{fontSize:22,fontWeight:800,color}}>{counts[key]||0}</div>
                  <div style={{fontSize:8,color,fontWeight:700,textTransform:'uppercase',marginTop:2,lineHeight:1.3}}>{label}</div>
                </div>
              ))}
            </div>

            <p style={{fontSize:11,color:'#64748B',marginBottom:10}}>
              {results.applied} entries updated. Pink and red entries are marked in the billing records — filter by insurance status to review.
              {results.matchResults._duplicateSkipped > 0 && (
                <div style={{marginTop:8,padding:'8px 12px',background:'#FEF3C7',border:'1px solid #FCD34D',borderRadius:7,fontSize:11,color:'#92400E',fontWeight:600}}>
                  ⚠ {results.matchResults._duplicateSkipped === results.matchResults._totalPending
                    ? `This remittance appears to already be imported — all ${results.matchResults._duplicateSkipped} pending claims are already in your queue.`
                    : `${results.matchResults._duplicateSkipped} of ${results.matchResults._totalPending} pending claims already exist in your queue from a previous import.`
                  }
                </div>
              )}
            </p>

            <div style={{maxHeight:360,overflow:'auto',border:'1px solid #E2E8F0',borderRadius:8}}>
              <table style={{width:'100%',borderCollapse:'collapse',fontSize:10}}>
                <thead style={{position:'sticky',top:0,background:'#F8FAFC',zIndex:1}}>
                  <tr>
                    {['Status','EOB Patient','EOB DOS','EOB $','Matched To','Entry Date','Ins Exp','Diff',''].map(h=>(
                      <th key={h} style={{padding:'6px 8px',textAlign:'left',fontSize:8,fontWeight:700,color:'#94A3B8',textTransform:'uppercase',borderBottom:'2px solid #E2E8F0',whiteSpace:'nowrap'}}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {results.matchResults.map((r,i)=>{
                    const statusInfo = STATUS[r.status] || {bg:'#F1F5F9',color:'#64748B',label:r.status};
                    const {bg,color,label} = statusInfo;
                    const entryInsExp = r.entry ? ((parseFloat(r.entry.ins1Amt)||0)+(parseFloat(r.entry.ins2Amt)||0)+(parseFloat(r.entry.ins3Amt)||0)) || (parseFloat(r.entry.ins)||0) : 0;
                    const expAmt = entryInsExp;
                    const diff = r.entry ? (r.claim.amount - expAmt) : null;
                    return (
                      <tr key={i} style={{background:i%2===0?'white':'#FAFBFC',borderBottom:'1px solid #F0F4F8'}}>
                        <td style={{padding:'4px 8px'}}>
                          <span style={{fontSize:8,fontWeight:700,color,background:bg,borderRadius:3,padding:'1px 5px',whiteSpace:'nowrap'}}>{label}</span>
                        </td>
                        <td style={{padding:'4px 8px',maxWidth:100,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{r.claim.memberName}</td>
                        <td style={{padding:'4px 8px',whiteSpace:'nowrap',color:'#64748B'}}>{r.claim.dos}</td>
                        <td style={{padding:'4px 8px',textAlign:'right',fontWeight:600,color:r.claim.negative?'#DC2626':'#1B3A5C'}}>${Math.abs(r.claim.amount).toFixed(2)}</td>
                        <td style={{padding:'4px 8px',maxWidth:100,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap',color:'#64748B'}}>{r.entry?.patientName||'—'}</td>
                        <td style={{padding:'4px 8px',color:r.entry&&r.claim.dos!==r.entry.date?'#DC2626':'#64748B',fontWeight:r.entry&&r.claim.dos!==r.entry.date?700:400}}>{r.entry?.date||'—'}</td>
                        <td style={{padding:'4px 8px',textAlign:'right',color:'#64748B'}}>{entryInsExp>0?`$${entryInsExp.toFixed(2)}`:'—'}</td>
                        <td style={{padding:'4px 8px',textAlign:'right',fontWeight:r.status==='amount_mismatch'?700:400,color:r.status==='amount_mismatch'?'#DC2626':'#10B981'}}>
                          {entryInsExp>0?(r.claim.amount-entryInsExp>0?'+':'')+(r.claim.amount-entryInsExp).toFixed(2):'—'}
                        </td>
                        {(r.insPaidState==='confirmed'||r.insPaidState==='partial')&&(
                          <td style={{padding:'4px 8px'}}>
                            <button onClick={async()=>{
                              if(!r.entry)return;
                              const {setDoc,doc}=await import('firebase/firestore');
                              const {db}=await import('./firebase');
                              const upd={...r.entry,insurancePaid1:'',insurancePaid2:'',insurancePaid3:'',insPaidState:'pending',updatedAt:new Date().toISOString()};
                              await setDoc(doc(db,'billingEntries',r.entry.id),upd);
                              // Push back to pending EOB queue
                              await setDoc(doc(db,'pendingEOB','undo_'+r.claim.claimNum+'_'+Date.now()),{
                                importedAt:new Date().toISOString(),
                                source:'undo',
                                claims:[{
                                  claimNum:r.claim.claimNum,memberName:r.claim.memberName,
                                  dos:r.claim.dos,amount:r.claim.amount,doctor:r.claim.doctor||'',
                                  status:'unmatched',reason:'Manually undone',
                                  suggestedEntryId:r.entry.id,suggestedEntryName:r.entry.patientName,
                                  suggestedEntryDate:r.entry.date,suggestedScore:0
                                }]
                              });
                              alert('Match cleared for '+r.entry.patientName+'. Added to pending EOB.');
                            }} style={{background:'#FEE2E2',border:'none',borderRadius:4,padding:'2px 6px',cursor:'pointer',fontSize:9,color:'#DC2626'}}>Undo</button>
                          </td>
                        )}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            <div style={{display:'flex',gap:8,marginTop:14}}>
              <button onClick={()=>{setStep('choose');setResults(null);setError('');}}
                style={{background:'#1B3A5C',color:'white',border:'none',borderRadius:7,padding:'9px 20px',cursor:'pointer',fontSize:13,fontWeight:600}}>Import Another</button>
              <button onClick={onClose}
                style={{background:'#F1F5F9',color:'#64748B',border:'none',borderRadius:7,padding:'9px 14px',cursor:'pointer',fontSize:13}}>Close</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export function matchClaimsExternal(claims, entries) { return matchClaims(claims, entries); }
